import { useState, useEffect } from "react";
import * as XLSX from "xlsx";

const STORAGE_KEY = "warehouse_items";

function loadItems() {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
  catch { return []; }
}
function saveItems(items) { localStorage.setItem(STORAGE_KEY, JSON.stringify(items)); }

export default function Warehouse() {
  const [items, setItems] = useState(loadItems);
  const [form, setForm] = useState({ name: "", unit: "С€С‚.", qty: "", min: "" });
  const [editId, setEditId] = useState(null);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");

  useEffect(() => { saveItems(items); }, [items]);

  const setF = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const addOrUpdate = () => {
    if (!form.name.trim()) return;
    if (editId !== null) {
      setItems(its => its.map(it => it.id === editId ? { ...it, ...form, qty: Number(form.qty), min: Number(form.min) } : it));
      setEditId(null);
    } else {
      setItems(its => [...its, { id: Date.now(), ...form, qty: Number(form.qty), min: Number(form.min) }]);
    }
    setForm({ name: "", unit: "С€С‚.", qty: "", min: "" });
  };

  const startEdit = (it) => { setEditId(it.id); setForm({ name: it.name, unit: it.unit, qty: it.qty, min: it.min }); };
  const cancelEdit = () => { setEditId(null); setForm({ name: "", unit: "С€С‚.", qty: "", min: "" }); };
  const deleteItem = (id) => { if (window.confirm("РЈРґР°Р»РёС‚СЊ С‚РѕРІР°СЂ?")) setItems(its => its.filter(it => it.id !== id)); };
  const updateQty = (id, delta) => { setItems(its => its.map(it => it.id === id ? { ...it, qty: Math.max(0, it.qty + delta) } : it)); };

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(items.map(i => ({ "РќР°Р·РІР°РЅРёРµ": i.name, "Р•Рґ. РёР·Рј.": i.unit, "РљРѕР»РёС‡РµСЃС‚РІРѕ": i.qty, "РњРёРЅ. РѕСЃС‚Р°С‚РѕРє": i.min || 0, "РЎС‚Р°С‚СѓСЃ": i.qty === 0 ? "РќРµС‚" : (i.min && i.qty <= i.min ? "РњР°Р»Рѕ" : "Р’ РЅР°Р»РёС‡РёРё") })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "РЎРєР»Р°Рґ");
    XLSX.writeFile(wb, "РЎРєР»Р°Рґ.xlsx");
  };

  const filtered = items.filter(it => {
    const matchSearch = it.name.toLowerCase().includes(search.toLowerCase());
    const matchFilter = filter === "all" || (filter === "low" && it.qty <= it.min && it.qty > 0) || (filter === "out" && it.qty === 0);
    return matchSearch && matchFilter;
  });

  const card = { background: "#1e2130", border: "1px solid #2d3354", borderRadius: 8, padding: "16px 20px", marginBottom: 16 };
  const inp = { padding: "6px 10px", border: "1px solid #2d3354", borderRadius: 4, fontSize: 13, boxSizing: "border-box" };
  const btn = { padding: "7px 16px", borderRadius: 4, border: "1px solid #2d3354", background: "#1e2130", cursor: "pointer", fontSize: 13 };
  const lbl = { fontSize: 12, color: "#7c8db5", marginBottom: 3, display: "block" };

  const statusColor = (it) => it.qty === 0 ? "#c00" : (it.min && it.qty <= it.min) ? "#e65100" : "#2e7d32";
  const statusText = (it) => it.qty === 0 ? "РќРµС‚ РІ РЅР°Р»РёС‡РёРё" : (it.min && it.qty <= it.min) ? "РњР°Р»Рѕ" : "Р’ РЅР°Р»РёС‡РёРё";

  const outCount = items.filter(it => it.qty === 0).length;
  const lowCount = items.filter(it => it.min && it.qty <= it.min && it.qty > 0).length;

  return (
    <div>
      <div style={{ display: "flex", gap: 12, marginBottom: 20, flexWrap: "wrap" }}>
        {[{ label: "Р’СЃРµРіРѕ РїРѕР·РёС†РёР№", value: items.length, color: "#1a5fa8" }, { label: "Р—Р°РєР°РЅС‡РёРІР°РµС‚СЃСЏ", value: lowCount, color: "#e65100" }, { label: "РќРµС‚ РІ РЅР°Р»РёС‡РёРё", value: outCount, color: "#c00" }].map((s, i) => (
          <div key={i} style={{ flex: 1, minWidth: 120, background: "#1e2130", border: "1px solid #2d3354", borderRadius: 8, padding: "12px 16px" }}>
            <div style={{ fontSize: 24, fontWeight: 700, color: s.color }}>{s.value}</div>
            <div style={{ fontSize: 12, color: "#7c8db5" }}>{s.label}</div>
          </div>
        ))}
      </div>

      <div style={card}>
        <p style={{ fontWeight: 500, marginBottom: 12, fontSize: 14 }}>{editId !== null ? "Р РµРґР°РєС‚РёСЂРѕРІР°С‚СЊ С‚РѕРІР°СЂ" : "Р”РѕР±Р°РІРёС‚СЊ С‚РѕРІР°СЂ"}</p>
        <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr", gap: 10, marginBottom: 10 }}>
          <div><label style={lbl}>РќР°Р·РІР°РЅРёРµ</label><input style={{ ...inp, width: "100%" }} value={form.name} onChange={e => setF("name", e.target.value)} placeholder="РќР°Р·РІР°РЅРёРµ С‚РѕРІР°СЂР°" /></div>
          <div><label style={lbl}>Р•Рґ. РёР·Рј.</label><input style={{ ...inp, width: "100%" }} value={form.unit} onChange={e => setF("unit", e.target.value)} /></div>
          <div><label style={lbl}>РљРѕР»РёС‡РµСЃС‚РІРѕ</label><input type="number" style={{ ...inp, width: "100%" }} value={form.qty} onChange={e => setF("qty", e.target.value)} placeholder="0" /></div>
          <div><label style={lbl}>РњРёРЅ. РѕСЃС‚Р°С‚РѕРє</label><input type="number" style={{ ...inp, width: "100%" }} value={form.min} onChange={e => setF("min", e.target.value)} placeholder="0" /></div>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={addOrUpdate} style={{ ...btn, background: "#1a5fa8", color: "#fff", borderColor: "#1a5fa8", fontWeight: 600 }}>{editId !== null ? "РЎРѕС…СЂР°РЅРёС‚СЊ" : "+ Р”РѕР±Р°РІРёС‚СЊ"}</button>
          {editId !== null && <button onClick={cancelEdit} style={btn}>РћС‚РјРµРЅР°</button>}
        </div>
      </div>

      <div style={{ display: "flex", gap: 10, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        <button onClick={exportExcel} style={{ ...btn, color: "#2e7d32", borderColor: "#2e7d32" }}>в¬‡ Excel</button>
        <input style={{ ...inp, flex: 1, minWidth: 180 }} value={search} onChange={e => setSearch(e.target.value)} placeholder="РџРѕРёСЃРє РїРѕ РЅР°Р·РІР°РЅРёСЋ..." />
        <div style={{ display: "flex", gap: 6 }}>
          {[["all","Р’СЃРµ"],["low","РњР°Р»Рѕ"],["out","РќРµС‚"]].map(([v, l]) => (
            <button key={v} onClick={() => setFilter(v)} style={{ ...btn, borderColor: filter===v?"#1a5fa8":"#ccc", color: filter===v?"#1a5fa8":"#333", fontWeight: filter===v?600:400 }}>{l}</button>
          ))}
        </div>
      </div>

      <div style={{ background: "#1e2130", border: "1px solid #2d3354", borderRadius: 8, overflow: "hidden" }}>
        {filtered.length === 0 ? (
          <div style={{ padding: 32, textAlign: "center", color: "#aaa", fontSize: 14 }}>{items.length === 0 ? "РЎРєР»Р°Рґ РїСѓСЃС‚РѕР№. Р”РѕР±Р°РІСЊС‚Рµ РїРµСЂРІС‹Р№ С‚РѕРІР°СЂ." : "РќРёС‡РµРіРѕ РЅРµ РЅР°Р№РґРµРЅРѕ."}</div>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
            <thead>
              <tr style={{ background: "#252a3d" }}>
                <th style={{ textAlign: "left", padding: "10px 14px", fontWeight: 600, color: "#444" }}>РќР°Р·РІР°РЅРёРµ</th>
                <th style={{ textAlign: "center", padding: "10px 8px", fontWeight: 600, color: "#444" }}>Р•Рґ.</th>
                <th style={{ textAlign: "center", padding: "10px 8px", fontWeight: 600, color: "#444" }}>РћСЃС‚Р°С‚РѕРє</th>
                <th style={{ textAlign: "center", padding: "10px 8px", fontWeight: 600, color: "#444" }}>РњРёРЅ.</th>
                <th style={{ textAlign: "center", padding: "10px 8px", fontWeight: 600, color: "#444" }}>РЎС‚Р°С‚СѓСЃ</th>
                <th style={{ textAlign: "center", padding: "10px 8px", fontWeight: 600, color: "#444" }}>РР·РјРµРЅРёС‚СЊ</th>
                <th style={{ width: 60 }}></th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((it, idx) => (
                <tr key={it.id} style={{ borderTop: "1px solid #f0f0f0", background: idx % 2 === 0 ? "#fff" : "#fafafa" }}>
                  <td style={{ padding: "10px 14px", fontWeight: 500 }}>{it.name}</td>
                  <td style={{ padding: "10px 8px", textAlign: "center", color: "#7c8db5" }}>{it.unit}</td>
                  <td style={{ padding: "10px 8px", textAlign: "center", fontWeight: 700, color: statusColor(it), fontSize: 15 }}>{it.qty}</td>
                  <td style={{ padding: "10px 8px", textAlign: "center", color: "#aaa" }}>{it.min || "вЂ”"}</td>
                  <td style={{ padding: "10px 8px", textAlign: "center" }}>
                    <span style={{ background: statusColor(it) + "18", color: statusColor(it), borderRadius: 4, padding: "3px 8px", fontSize: 12, fontWeight: 600 }}>{statusText(it)}</span>
                  </td>
                  <td style={{ padding: "10px 8px", textAlign: "center" }}>
                    <div style={{ display: "flex", gap: 4, justifyContent: "center" }}>
                      <button onClick={() => updateQty(it.id, -1)} style={{ ...btn, padding: "3px 10px", fontSize: 16, color: "#c00" }}>в€’</button>
                      <button onClick={() => updateQty(it.id, 1)} style={{ ...btn, padding: "3px 10px", fontSize: 16, color: "#2e7d32" }}>+</button>
                    </div>
                  </td>
                  <td style={{ padding: "10px 8px", textAlign: "center" }}>
                    <div style={{ display: "flex", gap: 4, justifyContent: "center" }}>
                      <button onClick={() => startEdit(it)} style={{ ...btn, padding: "3px 8px", fontSize: 12 }}>вњЋ</button>
                      <button onClick={() => deleteItem(it.id)} style={{ ...btn, padding: "3px 8px", fontSize: 12, color: "#c00" }}>вњ•</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
