import { useState, useEffect } from "react";
import * as XLSX from "xlsx";

const SETTINGS_KEY = "delivery_calc_settings";
const defaultSettings = { pricePerKg: 10, pricePerKm: 5, pricePerM3: 500, minPrice: 300 };

function loadSettings() {
  try { return { ...defaultSettings, ...JSON.parse(localStorage.getItem(SETTINGS_KEY)) }; }
  catch { return defaultSettings; }
}
function saveSettings(s) { localStorage.setItem(SETTINGS_KEY, JSON.stringify(s)); }

export default function DeliveryCalc() {
  const [settings, setSettings] = useState(loadSettings);
  const [showSettings, setShowSettings] = useState(false);
  const [form, setForm] = useState({ weight: "", distance: "", length: "", width: "", height: "", desc: "" });
  const [result, setResult] = useState(null);
  const [history, setHistory] = useState(() => {
    try { return JSON.parse(localStorage.getItem("delivery_calc_history")) || []; }
    catch { return []; }
  });

  useEffect(() => { localStorage.setItem("delivery_calc_history", JSON.stringify(history)); }, [history]);

  const setF = (k, v) => setForm(f => ({ ...f, [k]: v }));
  const setS = (k, v) => setSettings(s => ({ ...s, [k]: v }));

  const calculate = () => {
    const weight = parseFloat(form.weight) || 0;
    const distance = parseFloat(form.distance) || 0;
    const l = parseFloat(form.length) || 0;
    const w = parseFloat(form.width) || 0;
    const h = parseFloat(form.height) || 0;
    const volume = (l * w * h) / 1000000;
    const dimWeight = volume * 250;
    const billableWeight = Math.max(weight, dimWeight);
    const costWeight = billableWeight * settings.pricePerKg;
    const costDistance = distance * settings.pricePerKm;
    const costVolume = volume * settings.pricePerM3;
    const total = Math.max(costWeight + costDistance + costVolume, settings.minPrice);
    const res = { id: Date.now(), date: new Date().toLocaleDateString("ru-RU"), desc: form.desc || "Р‘РµР· РѕРїРёСЃР°РЅРёСЏ", weight, distance, volume: volume.toFixed(4), dimWeight: dimWeight.toFixed(2), billableWeight: billableWeight.toFixed(2), costWeight: costWeight.toFixed(2), costDistance: costDistance.toFixed(2), costVolume: costVolume.toFixed(2), total: total.toFixed(2) };
    setResult(res);
  };

  const saveToHistory = () => {
    if (!result) return;
    setHistory(h => [result, ...h].slice(0, 50));
    alert("Р Р°СЃС‡С‘С‚ СЃРѕС…СЂР°РЅС‘РЅ!");
  };

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(history.map(i => ({ "Р”Р°С‚Р°": i.date, "РћРїРёСЃР°РЅРёРµ": i.desc, "Р’РµСЃ, РєРі": i.weight, "Р Р°СЃСЃС‚РѕСЏРЅРёРµ, РєРј": i.distance, "РћР±СЉС‘Рј, РјВі": i.volume, "РС‚РѕРіРѕ, СЂСѓР±.": i.total })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Р Р°СЃС‡С‘С‚С‹");
    XLSX.writeFile(wb, "Р Р°СЃС‡С‘С‚С‹_РґРѕСЃС‚Р°РІРєРё.xlsx");
  };

  const deleteHistory = (id) => setHistory(h => h.filter(r => r.id !== id));
  const clearHistory = () => { if (window.confirm("РћС‡РёСЃС‚РёС‚СЊ РёСЃС‚РѕСЂРёСЋ?")) setHistory([]); };

  const inp = { padding: "6px 10px", border: "1px solid #2d3354", borderRadius: 4, fontSize: 13, boxSizing: "border-box", width: "100%" };
  const lbl = { fontSize: 12, color: "#7c8db5", marginBottom: 3, display: "block" };
  const card = { background: "#1e2130", border: "1px solid #2d3354", borderRadius: 8, padding: "16px 20px", marginBottom: 16 };
  const btn = { padding: "7px 16px", borderRadius: 4, border: "1px solid #2d3354", background: "#1e2130", cursor: "pointer", fontSize: 13 };

  return (
    <div>
      <div style={{ ...card, borderLeft: "4px solid #1a5fa8" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: showSettings ? 14 : 0 }}>
          <p style={{ fontWeight: 600, fontSize: 14, margin: 0 }}>вљ™пёЏ РўР°СЂРёС„ РґРѕСЃС‚Р°РІРєРё</p>
          <button onClick={() => { if (showSettings) saveSettings(settings); setShowSettings(!showSettings); }} style={{ ...btn, color: "#1a5fa8", borderColor: "#1a5fa8" }}>
            {showSettings ? "РЎРѕС…СЂР°РЅРёС‚СЊ С‚Р°СЂРёС„" : "РР·РјРµРЅРёС‚СЊ С‚Р°СЂРёС„"}
          </button>
        </div>
        {showSettings && (
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 10, marginTop: 14 }}>
            {[["pricePerKg","Р¦РµРЅР° Р·Р° РєРі, СЂСѓР±."],["pricePerKm","Р¦РµРЅР° Р·Р° РєРј, СЂСѓР±."],["pricePerM3","Р¦РµРЅР° Р·Р° РјВі, СЂСѓР±."],["minPrice","РњРёРЅ. СЃС‚РѕРёРјРѕСЃС‚СЊ, СЂСѓР±."]].map(([k, l]) => (
              <div key={k}><label style={lbl}>{l}</label><input type="number" style={inp} value={settings[k]} onChange={e => setS(k, parseFloat(e.target.value) || 0)} /></div>
            ))}
          </div>
        )}
        {!showSettings && (
          <div style={{ display: "flex", gap: 20, marginTop: 10, flexWrap: "wrap", fontSize: 13, color: "#a0aec0" }}>
            <span>Р—Р° РєРі: <b>{settings.pricePerKg} СЂСѓР±.</b></span>
            <span>Р—Р° РєРј: <b>{settings.pricePerKm} СЂСѓР±.</b></span>
            <span>Р—Р° РјВі: <b>{settings.pricePerM3} СЂСѓР±.</b></span>
            <span>РњРёРЅРёРјСѓРј: <b>{settings.minPrice} СЂСѓР±.</b></span>
          </div>
        )}
      </div>

      <div style={card}>
        <p style={{ fontWeight: 600, fontSize: 14, marginBottom: 14 }}>РќРѕРІС‹Р№ СЂР°СЃС‡С‘С‚</p>
        <div style={{ marginBottom: 10 }}><label style={lbl}>РћРїРёСЃР°РЅРёРµ РіСЂСѓР·Р°</label><input style={inp} value={form.desc} onChange={e => setF("desc", e.target.value)} placeholder="РќР°РїСЂРёРјРµСЂ: С…РѕР»РѕРґРёР»СЊРЅРёРє, РєРѕСЂРѕР±РєРё..." /></div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
          <div><label style={lbl}>Р’РµСЃ, РєРі</label><input type="number" style={inp} value={form.weight} onChange={e => setF("weight", e.target.value)} placeholder="0" /></div>
          <div><label style={lbl}>Р Р°СЃСЃС‚РѕСЏРЅРёРµ, РєРј</label><input type="number" style={inp} value={form.distance} onChange={e => setF("distance", e.target.value)} placeholder="0" /></div>
        </div>
        <p style={{ fontSize: 12, color: "#7c8db5", marginBottom: 8 }}>Р“Р°Р±Р°СЂРёС‚С‹ (РЅРµРѕР±СЏР·Р°С‚РµР»СЊРЅРѕ)</p>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 14 }}>
          {[["length","Р”Р»РёРЅР°, СЃРј"],["width","РЁРёСЂРёРЅР°, СЃРј"],["height","Р’С‹СЃРѕС‚Р°, СЃРј"]].map(([k, l]) => (
            <div key={k}><label style={lbl}>{l}</label><input type="number" style={inp} value={form[k]} onChange={e => setF(k, e.target.value)} placeholder="0" /></div>
          ))}
        </div>
        <button onClick={calculate} style={{ ...btn, background: "#1a5fa8", color: "#fff", borderColor: "#1a5fa8", fontWeight: 600 }}>Р Р°СЃСЃС‡РёС‚Р°С‚СЊ в†’</button>
      </div>

      {result && (
        <div style={{ ...card, borderLeft: "4px solid #2e7d32" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <p style={{ fontWeight: 600, fontSize: 14, margin: 0 }}>Р РµР·СѓР»СЊС‚Р°С‚ СЂР°СЃС‡С‘С‚Р°</p>
            <button onClick={saveToHistory} style={{ ...btn, color: "#2e7d32", borderColor: "#2e7d32" }}>РЎРѕС…СЂР°РЅРёС‚СЊ РІ РёСЃС‚РѕСЂРёСЋ</button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, fontSize: 13, marginBottom: 14 }}>
            <div style={{ color: "#7c8db5" }}>Р’РµСЃ С„Р°РєС‚РёС‡РµСЃРєРёР№:</div><div><b>{result.weight} РєРі</b></div>
            <div style={{ color: "#7c8db5" }}>РћР±СЉС‘РјРЅС‹Р№ РІРµСЃ:</div><div><b>{result.dimWeight} РєРі</b></div>
            <div style={{ color: "#7c8db5" }}>Р Р°СЃС‡С‘С‚РЅС‹Р№ РІРµСЃ:</div><div><b>{result.billableWeight} РєРі</b></div>
            <div style={{ color: "#7c8db5" }}>РћР±СЉС‘Рј:</div><div><b>{result.volume} РјВі</b></div>
            <div style={{ color: "#7c8db5" }}>РЎС‚РѕРёРјРѕСЃС‚СЊ Р·Р° РІРµСЃ:</div><div><b>{result.costWeight} СЂСѓР±.</b></div>
            <div style={{ color: "#7c8db5" }}>РЎС‚РѕРёРјРѕСЃС‚СЊ Р·Р° СЂР°СЃСЃС‚РѕСЏРЅРёРµ:</div><div><b>{result.costDistance} СЂСѓР±.</b></div>
            <div style={{ color: "#7c8db5" }}>РЎС‚РѕРёРјРѕСЃС‚СЊ Р·Р° РѕР±СЉС‘Рј:</div><div><b>{result.costVolume} СЂСѓР±.</b></div>
          </div>
          <div style={{ background: "#f0f7f0", borderRadius: 8, padding: "14px 20px", textAlign: "center" }}>
            <div style={{ fontSize: 13, color: "#a0aec0", marginBottom: 4 }}>РС‚РѕРіРѕРІР°СЏ СЃС‚РѕРёРјРѕСЃС‚СЊ РґРѕСЃС‚Р°РІРєРё</div>
            <div style={{ fontSize: 32, fontWeight: 700, color: "#2e7d32" }}>{result.total} СЂСѓР±.</div>
          </div>
        </div>
      )}

      {history.length > 0 && (
        <div style={card}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <p style={{ fontWeight: 600, fontSize: 14, margin: 0 }}>РСЃС‚РѕСЂРёСЏ СЂР°СЃС‡С‘С‚РѕРІ</p>
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={exportExcel} style={{ ...btn, color: "#2e7d32", borderColor: "#2e7d32", fontSize: 12 }}>в¬‡ Excel</button>
              <button onClick={clearHistory} style={{ ...btn, color: "#c00", borderColor: "#c00", fontSize: 12 }}>РћС‡РёСЃС‚РёС‚СЊ РІСЃС‘</button>
            </div>
          </div>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
            <thead>
              <tr style={{ background: "#252a3d" }}>
                <th style={{ textAlign: "left", padding: "8px 10px", fontWeight: 600, color: "#444" }}>Р”Р°С‚Р°</th>
                <th style={{ textAlign: "left", padding: "8px 10px", fontWeight: 600, color: "#444" }}>РћРїРёСЃР°РЅРёРµ</th>
                <th style={{ textAlign: "center", padding: "8px 10px", fontWeight: 600, color: "#444" }}>Р’РµСЃ</th>
                <th style={{ textAlign: "center", padding: "8px 10px", fontWeight: 600, color: "#444" }}>РљРј</th>
                <th style={{ textAlign: "right", padding: "8px 10px", fontWeight: 600, color: "#444" }}>РС‚РѕРіРѕ</th>
                <th style={{ width: 40 }}></th>
              </tr>
            </thead>
            <tbody>
              {history.map((r, i) => (
                <tr key={r.id} style={{ borderTop: "1px solid #f0f0f0", background: i % 2 === 0 ? "#fff" : "#fafafa" }}>
                  <td style={{ padding: "8px 10px" }}>{r.date}</td>
                  <td style={{ padding: "8px 10px" }}>{r.desc}</td>
                  <td style={{ padding: "8px 10px", textAlign: "center" }}>{r.weight} РєРі</td>
                  <td style={{ padding: "8px 10px", textAlign: "center" }}>{r.distance} РєРј</td>
                  <td style={{ padding: "8px 10px", textAlign: "right", fontWeight: 700, color: "#2e7d32" }}>{r.total} СЂСѓР±.</td>
                  <td style={{ padding: "8px 10px", textAlign: "center" }}>
                    <button onClick={() => deleteHistory(r.id)} style={{ ...btn, padding: "2px 7px", fontSize: 12, color: "#c00" }}>вњ•</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
